#!/usr/bin/env python3
"""CPU-only, file-only layered compositor. Inputs are generated by Lightek."""
import json
import math
from pathlib import Path
import re
import resource
import subprocess
import sys
import time

root=Path(sys.argv[2]).resolve()
spec=json.loads(Path(sys.argv[1]).read_text())
canvas=spec['canvas'];width=int(canvas['width']);height=int(canvas['height']);fps=int(canvas['fps']);duration=float(canvas['duration'])
if not (160<=width<=1920 and 90<=height<=1920 and width*height<=1920*1080 and 0<duration<=10 and 1<=fps<=24): raise ValueError('Invalid canvas')
layers=spec['layers']
if not 1<=len(layers)<=24: raise ValueError('Invalid layer count')
started=time.monotonic();rendered=[]
def run(command,timeout=30):
    result=subprocess.run(command,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=timeout)
    if result.returncode:
        raise RuntimeError(command[0]+' failed: '+result.stderr.decode(errors='replace')[-1200:])
    return result.stdout.decode().strip()
for index,layer in enumerate(layers):
    source=layer['source']
    if not re.fullmatch(r'source-\d+\.(svg|png)',source) or (root/source).is_symlink() or (root/source).resolve().parent!=root: raise ValueError('Invalid source')
    values=[layer[key] for key in ('width','height','rotation','depth','opacity','x','y')]
    if not all(isinstance(value,(int,float)) and math.isfinite(value) for value in values): raise ValueError('Invalid layer values')
    w=max(1,round(layer['width']));h=max(1,round(layer['height']))
    if max(w,h)>4096 or not 0<=layer['depth']<=1 or not 0<=layer['opacity']<=1: raise ValueError('Invalid layer bounds')
    output=root/f'layer-{index}.png'
    fit=layer.get('fit','stretch')
    resize=['-resize',f'{w}x{h}!'] if fit=='stretch' else ['-resize',f'{w}x{h}'+('^' if fit=='cover' else ''),'-gravity','center','-extent',f'{w}x{h}']
    input_path=root/source
    if layer['source_kind']=='svg':
        input_path=root/f'raster-{index}.png'
        run(['ffmpeg','-v','error','-y','-protocol_whitelist','file,pipe','-i',str(root/source),'-frames:v','1',str(input_path)])
    input_file=str(input_path)+'[0]'
    command=['convert','-limit','thread','1','-limit','memory','96MiB','-limit','map','96MiB','-limit','disk','128MiB',
        '-background','none',input_file,*resize,
        '-alpha','set','-channel','A','-evaluate','multiply',str(layer['opacity']),'+channel','-rotate',str(layer['rotation']),'PNG32:'+str(output)]
    run(command)
    ow,oh=map(int,run(['identify','-format','%w %h',str(output)]).split())
    rendered.append((output,layer,ow,oh))
command=['ffmpeg','-v','error','-y','-filter_complex_threads','1','-f','lavfi','-i',f'color=c=0x121820:s={width}x{height}:r={fps}:d={duration}']
for output,_,_,_ in rendered:
    command+=['-protocol_whitelist','file,pipe','-loop','1','-framerate',str(fps),'-i',str(output)]
filters=[];previous='0:v'
for index,(_,layer,w,h) in enumerate(rendered):
    dx=float(spec['camera']['x'])*width*layer['depth'];dy=float(spec['camera']['y'])*height*layer['depth']
    label=f'v{index}'
    x=f'{layer["x"]-w/2:.6f}-({dx:.6f})*t/{duration:.6f}'
    y=f'{layer["y"]-h/2:.6f}-({dy:.6f})*t/{duration:.6f}'
    filters.append(f'[{previous}][{index+1}:v]overlay=x=\'{x}\':y=\'{y}\':eval=frame:format=auto[{label}]')
    previous=label
command+=['-filter_complex',';'.join(filters),'-map',f'[{previous}]','-t',str(duration),'-r',str(fps),'-an','-c:v','libx264',
    '-threads','1','-preset','veryfast','-crf','20','-pix_fmt','yuv420p','-movflags','+faststart',str(root/'scene.mp4')]
run(command,timeout=150)
metrics={'engine':'lightek_2d','layers':len(layers),'duration':duration,'width':width,'height':height,
    'elapsed_seconds':round(time.monotonic()-started,3),'peak_child_rss_mib':round(resource.getrusage(resource.RUSAGE_CHILDREN).ru_maxrss/1024,2)}
(root/'metrics.json').write_text(json.dumps(metrics))
print(json.dumps(metrics))
